using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;
namespace GearLab {public static class Robot671Audit {
 public static int Run(string folder){Directory.CreateDirectory(folder);try{var d=ReferenceRobot67.Cached();var build=RobotCad.Build(d);int total=0;using(var kernel=new CADKernel()){var poses=new[]{new[]{0.0,-10,25,0,15,0},new[]{0.0,0,0,0,0,0},new[]{0.0,30,-60,0,30,0},new[]{0.0,20,-35,15,-20,25},new[]{30.0,-20,35,-30,25,45},new[]{-30.0,15,-30,45,-30,-45}};for(int n=0;n<poses.Length;n++){for(int j=0;j<6;j++)d.Joints[j].Position=poses[n][j];build.InvalidatePose();File.WriteAllText(Path.Combine(folder,"audit-progress.txt"),"pose "+n);var parts=build.Entries.Values.Where(e=>!e.Guide&&e.Category!="Крепёж"&&e.Category!="Проводка"&&e.Part.BearingSource==null&&!e.Id.Contains("cable_guide")).Select(e=>new{Id=e.Id,Step=e.Part.Analytic==null?CADNativeBridge.FromLegacyPart(e.Part).Features[0].Data:null,Analytic=e.Part.Analytic,Transform=CADNativeBridge.Transform(build.Pose(e.Id,0,false)),Integral=e.Category=="Мотор"?e.JointId+"_motor_integral":null}).ToArray();var spec=new{Parts=parts};File.WriteAllText(Path.Combine(folder,"pose-"+n+"-request.json"),CADDocument.Serializer().Serialize(new{Spec=spec}),Encoding.UTF8);var result=kernel.Run(new CADDocument(),"assembly_contacts",null,null,null,new Dictionary<string,object>{{"Spec",spec}}).Motion;total+=result.Collisions.Count;File.WriteAllText(Path.Combine(folder,"pose-"+n+"-results.json"),CADDocument.Serializer().Serialize(result),Encoding.UTF8);}}File.WriteAllText(Path.Combine(folder,"robot671-contact-results.json"),CADDocument.Serializer().Serialize(new{Poses=6,Collisions=total,Passed=total==0,FullRangeCertified=false,Scope="Housings, shafts, motors and gripper; fasteners, rolling bearings and flexible guides excluded"}),Encoding.UTF8);return total==0?0:1;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"audit-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
}}
